[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create &amp; Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --orange: #FF7A00;
      --white: #ffffff;
      --gray-50: #f9f9f9;
      --gray-100: #f3f3f3;
      --gray-200: #e8e8e8;
      --gray-400: #999;
      --gray-600: #555;
      --gray-800: #222;
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-xl: 32px;
      --font: 'Plus Jakarta Sans', sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--white);
      color: var(--black);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ── HEADER ── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 68px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      color: var(--black);
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 20px; height: 20px; fill: white; }

    .logo-name {
      font-size: 1.2rem;
      font-weight: 800;
      letter-spacing: -0.5px;
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-login {
      padding: 9px 22px;
      background: var(--black);
      color: var(--white);
      border: none;
      border-radius: 50px;
      font-family: var(--font);
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      text-decoration: none;
      transition: background 0.2s, transform 0.15s;
    }

    .btn-login:hover { background: var(--purple); transform: translateY(-1px); }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      padding: 6px;
      background: none;
      border: none;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: all 0.3s;
    }

    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile nav overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      inset: 0;
      top: 68px;
      background: var(--white);
      z-index: 99;
      padding: 32px 24px;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
    }

    .mobile-nav.open { display: flex; }

    .mobile-nav a {
      font-size: 1.3rem;
      font-weight: 700;
      color: var(--black);
      text-decoration: none;
      padding: 14px 0;
      border-bottom: 1px solid var(--gray-200);
      transition: color 0.2s;
    }

    .mobile-nav a:hover { color: var(--purple); }

    /* ── HERO ── */
    .hero {
      position: relative;
      min-height: 88vh;
      display: flex;
      align-items: center;
      overflow: hidden;
      background: #0a0a0a;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 70% 60% at 70% 50%, rgba(118,56,250,0.45) 0%, transparent 65%),
        radial-gradient(ellipse 50% 50% at 20% 80%, rgba(255,122,0,0.3) 0%, transparent 60%),
        radial-gradient(ellipse 40% 40% at 90% 10%, rgba(255,60,120,0.25) 0%, transparent 55%);
    }

    .hero-grid {
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      background-size: 60px 60px;
    }

    .hero-content {
      position: relative;
      max-width: 1200px;
      margin: 0 auto;
      padding: 80px 24px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .hero-text {}

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(118,56,250,0.2);
      border: 1px solid rgba(118,56,250,0.4);
      border-radius: 50px;
      padding: 6px 16px;
      color: #c4a8ff;
      font-size: 0.8rem;
      font-weight: 600;
      letter-spacing: 0.5px;
      margin-bottom: 28px;
    }

    .hero-badge::before {
      content: '';
      width: 6px; height: 6px;
      background: var(--purple);
      border-radius: 50%;
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }

    .hero h1 {
      font-size: clamp(2.4rem, 5vw, 4rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -1.5px;
      color: var(--white);
      margin-bottom: 24px;
    }

    .hero h1 .accent {
      background: linear-gradient(90deg, var(--purple), #e040fb, var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-desc {
      font-size: 1.1rem;
      color: rgba(255,255,255,0.65);
      margin-bottom: 40px;
      max-width: 460px;
      line-height: 1.7;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 16px 36px;
      background: linear-gradient(135deg, var(--purple), #e040fb);
      color: var(--white);
      border: none;
      border-radius: 50px;
      font-family: var(--font);
      font-size: 1.05rem;
      font-weight: 700;
      cursor: pointer;
      text-decoration: none;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 8px 32px rgba(118,56,250,0.4);
    }

    .hero-cta:hover { transform: translateY(-2px); box-shadow: 0 12px 40px rgba(118,56,250,0.55); }

    .hero-cta-arrow { font-size: 1.2em; }

    .hero-visual {
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .hero-phone-mock {
      position: relative;
      width: 240px;
    }

    .phone-frame {
      width: 240px;
      height: 480px;
      background: linear-gradient(160deg, #1a1a2e, #16213e);
      border-radius: 36px;
      border: 2px solid rgba(118,56,250,0.5);
      box-shadow:
        0 0 0 6px rgba(118,56,250,0.1),
        0 40px 80px rgba(0,0,0,0.6);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: 24px 16px;
      gap: 12px;
    }

    .phone-story {
      width: 100%;
      height: 130px;
      border-radius: 16px;
      background: linear-gradient(135deg, var(--purple) 0%, #e040fb 50%, var(--orange) 100%);
      position: relative;
      overflow: hidden;
      display: flex;
      align-items: flex-end;
      padding: 10px;
    }

    .phone-story::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='120' height='130' viewBox='0 0 120 130' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='60' cy='50' r='30' fill='rgba(255,255,255,0.15)'/%3E%3Ccircle cx='60' cy='50' r='18' fill='rgba(255,255,255,0.2)'/%3E%3C/svg%3E") center/cover;
    }

    .phone-story-label {
      font-size: 0.6rem;
      font-weight: 700;
      color: white;
      text-shadow: 0 1px 4px rgba(0,0,0,0.5);
      position: relative;
    }

    .phone-feed-item {
      width: 100%;
      height: 56px;
      background: rgba(255,255,255,0.07);
      border-radius: 12px;
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 0 10px;
    }

    .feed-avatar {
      width: 32px; height: 32px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .feed-avatar-1 { background: linear-gradient(135deg, #f093fb, #f5576c); }
    .feed-avatar-2 { background: linear-gradient(135deg, #4facfe, #00f2fe); }
    .feed-avatar-3 { background: linear-gradient(135deg, #43e97b, #38f9d7); }

    .feed-lines { flex: 1; display: flex; flex-direction: column; gap: 5px; }
    .feed-line { height: 6px; background: rgba(255,255,255,0.15); border-radius: 3px; }
    .feed-line.short { width: 55%; }

    .phone-hearts {
      display: flex;
      gap: 8px;
      align-items: center;
      width: 100%;
      padding: 0 4px;
    }

    .heart-bubble {
      width: 28px; height: 28px;
      background: rgba(255,255,255,0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.75rem;
    }

    .floating-badge {
      position: absolute;
      background: var(--white);
      border-radius: 16px;
      padding: 10px 16px;
      box-shadow: 0 8px 32px rgba(0,0,0,0.25);
      font-size: 0.8rem;
      font-weight: 700;
      white-space: nowrap;
    }

    .badge-top {
      top: 60px;
      right: -30px;
      color: var(--purple);
      animation: floatY 3s ease-in-out infinite;
    }

    .badge-bottom {
      bottom: 100px;
      left: -40px;
      color: var(--orange);
      animation: floatY 3s ease-in-out infinite 1.5s;
    }

    @keyframes floatY {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    /* ── SECTIONS SHARED ── */
    .section {
      padding: 100px 24px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-full { max-width: 100%; padding: 0; }

    /* ── FEATURES ── */
    .features-section { background: var(--white); }

    .features-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 100px 24px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .section-label {
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 2px;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 16px;
    }

    .features-inner h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.8px;
      margin-bottom: 24px;
    }

    .features-inner p {
      font-size: 1rem;
      color: var(--gray-600);
      line-height: 1.75;
      margin-bottom: 32px;
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      color: var(--purple);
      font-weight: 700;
      font-size: 0.95rem;
      text-decoration: none;
      border-bottom: 2px solid transparent;
      transition: border-color 0.2s, gap 0.2s;
    }

    .link-arrow:hover { border-color: var(--purple); gap: 10px; }

    .features-cards {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .feature-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }

    .feature-card:nth-child(2) { margin-top: 28px; }
    .feature-card:nth-child(4) { margin-top: 28px; }

    .fc-icon {
      width: 44px; height: 44px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
      margin-bottom: 16px;
    }

    .fc-icon-1 { background: linear-gradient(135deg, rgba(118,56,250,0.15), rgba(118,56,250,0.05)); }
    .fc-icon-2 { background: linear-gradient(135deg, rgba(255,122,0,0.15), rgba(255,122,0,0.05)); }
    .fc-icon-3 { background: linear-gradient(135deg, rgba(224,64,251,0.15), rgba(224,64,251,0.05)); }
    .fc-icon-4 { background: linear-gradient(135deg, rgba(0,200,150,0.15), rgba(0,200,150,0.05)); }

    .fc-title { font-size: 0.95rem; font-weight: 700; margin-bottom: 6px; }
    .fc-desc { font-size: 0.82rem; color: var(--gray-600); line-height: 1.5; }

    /* ── SAFETY ── */
    .safety-section {
      background: linear-gradient(135deg, #f0f4ff 0%, #faf5ff 50%, #fff8f0 100%);
    }

    .safety-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 100px 24px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .safety-visual {
      order: -1;
      display: flex;
      justify-content: center;
    }

    .safety-shield {
      width: 280px;
      height: 320px;
      background: var(--white);
      border-radius: 40% 40% 50% 50% / 30% 30% 70% 70%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 16px;
      box-shadow: 0 20px 60px rgba(118,56,250,0.15);
      border: 2px solid rgba(118,56,250,0.12);
      padding: 40px 32px;
    }

    .shield-icon {
      font-size: 3.5rem;
      filter: drop-shadow(0 4px 12px rgba(118,56,250,0.3));
    }

    .shield-items {
      display: flex;
      flex-direction: column;
      gap: 8px;
      width: 100%;
    }

    .shield-item {
      display: flex;
      align-items: center;
      gap: 10px;
      background: linear-gradient(90deg, rgba(118,56,250,0.08), rgba(118,56,250,0.02));
      border-radius: 10px;
      padding: 8px 14px;
      font-size: 0.78rem;
      font-weight: 600;
      color: var(--gray-800);
    }

    .shield-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: var(--purple);
      flex-shrink: 0;
    }

    .safety-inner h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.8px;
      margin-bottom: 24px;
    }

    .safety-inner p {
      font-size: 1rem;
      color: var(--gray-600);
      line-height: 1.75;
      margin-bottom: 32px;
    }

